doc.pages.filter(p=>/^Proto macOS /.test(p.name)).forEach(p=>p.layers.filter(s=>s.name.indexOf('Screen/macos/')===0&&s.name.split('/')[4].indexOf('settings')===0).forEach(s=>{var sb=s.layers.find(l=>l.name==='sidebar');var foot=sb.layers.find(l=>l.name==='link:settings');foot.stackLayout.gap=6;foot.stackLayout.apply();H.out({id:s.id,footer:foot.layers.map(l=>({n:l.name,x:l.frame.x,w:l.frame.width}))});}));